-- PrivaFuse central schema for Supabase (PostgreSQL).
-- Generated by scripts/print_schema.py from backend/app/models/tables.py. Do not edit by hand.
--
-- The coordinator stores metadata, metrics, aggregated analytics and audit
-- records only. There is deliberately no table for patient-level data.
--
-- Run this once in the Supabase SQL editor. (The API also creates missing
-- tables on start-up, but it does not enable row level security.)

CREATE TABLE IF NOT EXISTS users (
    id TEXT PRIMARY KEY,
    email TEXT NOT NULL UNIQUE,
    display_name TEXT,
    role TEXT NOT NULL,
    hospital_id TEXT,
    created_at TIMESTAMPTZ NOT NULL,
    last_login_at TIMESTAMPTZ,
    jurisdiction JSONB
);

CREATE TABLE IF NOT EXISTS local_credentials (
    user_id TEXT PRIMARY KEY,
    password_hash TEXT NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS hospitals (
    id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    kind TEXT,
    online BOOLEAN NOT NULL,
    modalities JSONB NOT NULL,
    data_summary JSONB,
    is_simulated BOOLEAN NOT NULL,
    last_activity_at TIMESTAMPTZ,
    created_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS fl_rounds (
    id TEXT PRIMARY KEY,
    round_number BIGINT NOT NULL,
    modality TEXT NOT NULL,
    status TEXT NOT NULL,
    config JSONB NOT NULL,
    base_model_version BIGINT NOT NULL,
    result_model_version BIGINT,
    num_participants BIGINT NOT NULL,
    aggregation_status TEXT NOT NULL,
    global_metrics JSONB,
    error TEXT,
    created_by TEXT,
    is_simulated BOOLEAN NOT NULL,
    started_at TIMESTAMPTZ NOT NULL,
    ended_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS fl_participants (
    id TEXT PRIMARY KEY,
    round_id TEXT NOT NULL,
    hospital_id TEXT NOT NULL,
    status TEXT NOT NULL,
    num_samples BIGINT,
    local_metrics JSONB,
    evaluation JSONB,
    error TEXT,
    joined_at TIMESTAMPTZ,
    update_received_at TIMESTAMPTZ,
    evaluated_at TIMESTAMPTZ
);

CREATE TABLE IF NOT EXISTS model_registry (
    id TEXT PRIMARY KEY,
    modality TEXT NOT NULL,
    version BIGINT NOT NULL,
    architecture TEXT NOT NULL,
    backend TEXT NOT NULL,
    architecture_signature TEXT NOT NULL,
    num_parameters BIGINT NOT NULL,
    round_id TEXT,
    status TEXT NOT NULL,
    weights_path TEXT,
    weights_sha256 TEXT NOT NULL,
    size_bytes BIGINT NOT NULL,
    metrics JSONB,
    dataset JSONB,
    is_simulated BOOLEAN NOT NULL,
    created_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS model_updates (
    id TEXT PRIMARY KEY,
    round_id TEXT NOT NULL,
    hospital_id TEXT NOT NULL,
    modality TEXT NOT NULL,
    architecture_signature TEXT,
    num_samples BIGINT,
    weights_sha256 TEXT,
    size_bytes BIGINT,
    update_norm DOUBLE PRECISION,
    dp_report JSONB,
    status TEXT NOT NULL,
    rejection_reason TEXT,
    storage_path TEXT,
    received_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS training_metrics (
    id BIGSERIAL PRIMARY KEY,
    round_id TEXT NOT NULL,
    modality TEXT NOT NULL,
    model_version BIGINT,
    scope TEXT NOT NULL,
    hospital_id TEXT,
    split TEXT NOT NULL,
    metrics JSONB NOT NULL,
    num_samples BIGINT,
    created_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS analytics_results (
    id BIGSERIAL PRIMARY KEY,
    kind TEXT NOT NULL,
    result_key TEXT NOT NULL,
    payload JSONB NOT NULL,
    model_version BIGINT,
    is_simulated BOOLEAN NOT NULL,
    generated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS forecasts (
    id BIGSERIAL PRIMARY KEY,
    region_id TEXT NOT NULL,
    disease TEXT NOT NULL,
    horizon BIGINT NOT NULL,
    model_name TEXT NOT NULL,
    payload JSONB NOT NULL,
    data_through TEXT NOT NULL,
    is_simulated BOOLEAN NOT NULL,
    generated_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS audit_logs (
    id BIGSERIAL PRIMARY KEY,
    timestamp TIMESTAMPTZ NOT NULL,
    actor TEXT NOT NULL,
    action TEXT NOT NULL,
    hospital_id TEXT,
    round_id TEXT,
    model_version TEXT,
    status TEXT NOT NULL,
    details JSONB,
    previous_hash TEXT NOT NULL,
    current_hash TEXT NOT NULL
);

CREATE TABLE IF NOT EXISTS regions (
    region_id TEXT PRIMARY KEY,
    name TEXT NOT NULL,
    population BIGINT,
    geometry JSONB NOT NULL,
    centroid_lon DOUBLE PRECISION,
    centroid_lat DOUBLE PRECISION,
    neighbours JSONB,
    is_simulated BOOLEAN NOT NULL
);

CREATE TABLE IF NOT EXISTS surveillance_reports (
    id BIGSERIAL PRIMARY KEY,
    hospital_id TEXT NOT NULL,
    region_id TEXT NOT NULL,
    disease TEXT NOT NULL,
    week_start TEXT NOT NULL,
    case_count BIGINT,
    suppressed BOOLEAN NOT NULL,
    is_simulated BOOLEAN NOT NULL
);

CREATE TABLE IF NOT EXISTS node_heartbeats (
    hospital_id TEXT PRIMARY KEY,
    hostname TEXT,
    ml_backend TEXT,
    device TEXT,
    software_version TEXT,
    architectures JSONB,
    data_summary JSONB,
    connected_since TIMESTAMPTZ NOT NULL,
    last_seen_at TIMESTAMPTZ NOT NULL
);

CREATE TABLE IF NOT EXISTS hospital_settings (
    hospital_id TEXT PRIMARY KEY,
    participating BOOLEAN NOT NULL,
    updated_at TIMESTAMPTZ NOT NULL,
    updated_by TEXT
);

CREATE UNIQUE INDEX IF NOT EXISTS uq_fl_participants_round_id_hospital_id ON fl_participants (round_id, hospital_id);

CREATE UNIQUE INDEX IF NOT EXISTS uq_model_registry_modality_version ON model_registry (modality, version);

CREATE UNIQUE INDEX IF NOT EXISTS uq_analytics_results_kind_result_key ON analytics_results (kind, result_key);

CREATE UNIQUE INDEX IF NOT EXISTS uq_forecasts_region_id_disease_horizon ON forecasts (region_id, disease, horizon);

CREATE UNIQUE INDEX IF NOT EXISTS uq_surveillance_reports_hospital_id_region_id_disease_week_start ON surveillance_reports (hospital_id, region_id, disease, week_start);

CREATE INDEX IF NOT EXISTS ix_fl_rounds_modality_round_number ON fl_rounds (modality, round_number);

CREATE INDEX IF NOT EXISTS ix_training_metrics_round_id ON training_metrics (round_id);

CREATE INDEX IF NOT EXISTS ix_training_metrics_modality_scope ON training_metrics (modality, scope);

CREATE INDEX IF NOT EXISTS ix_model_updates_round_id ON model_updates (round_id);

CREATE INDEX IF NOT EXISTS ix_audit_logs_timestamp ON audit_logs (timestamp);

CREATE INDEX IF NOT EXISTS ix_audit_logs_action ON audit_logs (action);

CREATE INDEX IF NOT EXISTS ix_surveillance_reports_disease_week_start ON surveillance_reports (disease, week_start);


-- Row level security.
-- The web app never queries these tables directly: it talks to the FastAPI
-- backend, which connects with DATABASE_URL. Enabling RLS with no policies
-- means the public `anon` and `authenticated` API roles can read nothing,
-- even if someone obtains the anon key.

ALTER TABLE users ENABLE ROW LEVEL SECURITY;
ALTER TABLE local_credentials ENABLE ROW LEVEL SECURITY;
ALTER TABLE hospitals ENABLE ROW LEVEL SECURITY;
ALTER TABLE fl_rounds ENABLE ROW LEVEL SECURITY;
ALTER TABLE fl_participants ENABLE ROW LEVEL SECURITY;
ALTER TABLE model_registry ENABLE ROW LEVEL SECURITY;
ALTER TABLE model_updates ENABLE ROW LEVEL SECURITY;
ALTER TABLE training_metrics ENABLE ROW LEVEL SECURITY;
ALTER TABLE analytics_results ENABLE ROW LEVEL SECURITY;
ALTER TABLE forecasts ENABLE ROW LEVEL SECURITY;
ALTER TABLE audit_logs ENABLE ROW LEVEL SECURITY;
ALTER TABLE regions ENABLE ROW LEVEL SECURITY;
ALTER TABLE surveillance_reports ENABLE ROW LEVEL SECURITY;
ALTER TABLE node_heartbeats ENABLE ROW LEVEL SECURITY;
ALTER TABLE hospital_settings ENABLE ROW LEVEL SECURITY;
